/**
 * Walks every organization that has not been deleted, one page at a time.
 */
import * as orgRepo from "@/server/repositories/organization-repository";
import type { OrgId } from "@/types/common";
import type { Organization } from "@/types/organization";

/** Organizations read per page when no page size is given. */
const DEFAULT_PAGE_SIZE = 50;

/**
 * Yields each live org exactly once per sweep. Fleet-wide jobs iterate this
 * rather than a bounded batch, so a run covers every tenant however many
 * there are, while only one page is held in memory at a time.
 */
export async function* eachLiveOrg(
  pageSize: number = DEFAULT_PAGE_SIZE,
): AsyncGenerator<Organization> {
  const limit = Math.max(1, pageSize);
  let after: OrgId | null = null;

  for (;;) {
    const page = await orgRepo.listLiveOrgs({ after, limit });
    yield* page;

    const last = page.at(-1);
    if (!last || page.length < limit) return;
    after = last.id;
  }
}

