import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as usageService from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
const tenants: Tenant[] = [];
const PAST = "2026-01-01T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  for (let i = 0; i < 130; i += 1) {
    const t = await createTenant(`scn-${i}`);
    if (i % 2 === 0) await usageRepo.recomputeUsage(t.org.id);
    tenants.push(t);
  }
});
afterAll(() => cleanup());

describe("scenario", () => {
  it("overdue covers all live orgs, not deleted ones", async () => {
    const issues = new Map<string, string>();
    for (const t of tenants) {
      const n = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
      const issue = await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { title: "late", dueAt: PAST }), t.userIds.owner, n);
      issues.set(t.org.id, issue.id);
    }
    await orgRepo.archiveOrg(tenants[7]!.org.id);
    const seen: string[] = [];
    const off = subscribe("issue.overdue", (p) => { seen.push(p.orgId); });
    const r = await runOverdueIssueJob(NOW);
    await runOverdueIssueJob(NOW);
    off();
    expect(r.processed).toBe(129);
    expect(seen).toHaveLength(129);
    expect(new Set(seen).size).toBe(129);
    expect(seen).not.toContain(tenants[7]!.org.id);
  });

  it("cleanup covers all orgs", async () => {
    for (const t of tenants) {
      const id = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
      const issue = await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { title: "old" }), t.userIds.owner, id);
      await searchRepo.upsertSearchDocument(t.org.id, "issue", issue.id, "old", null);
      await issueRepo.archiveIssue(t.org.id, issue.id);
    }
    const r = await runCleanupArchivedJob(new Date("2099-01-01T00:00:00.000Z"));
    let left = 0;
    for (const t of tenants) left += await searchRepo.countIndexed(t.org.id);
    expect(left).toBe(1); // only the deleted org's doc remains
    expect(r.failed).toBe(0);
  });

  it("rollup cycles through the queue", async () => {
    const spy = vi.spyOn(usageService, "recomputeUsage");
    const live = tenants.filter((_, i) => i !== 7).map((t) => t.org.id);
    const seen = new Set<string>();
    const runs: string[][] = [];
    for (let run = 0; run < 6; run += 1) {
      spy.mockClear();
      await runUsageRollupJob(NOW);
      const ids = spy.mock.calls.map((c) => c[0] as string);
      expect(ids.length).toBe(25);
      runs.push(ids);
      ids.forEach((id) => seen.add(id));
      // increments must not move anyone
      await usageRepo.incrementUsage(ids[0] as never, { issuesUsed: 5 });
    }
    expect(seen.size).toBe(129);
    // first run: never-recounted (odd) first
    expect(runs[0]!.every((id) => tenants.findIndex((t) => t.org.id === id) % 2 === 1)).toBe(true);
    // run 6 wraps around to the first recounted in run 1
    expect(runs[5]!.slice(0, 21)).toEqual(runs[0]!.slice(0, 21));
    expect(live.length).toBe(129);
    spy.mockRestore();
  });
});
EOF
